import os
import secrets
import urllib.parse
from typing import Dict, Optional

import requests


AUTH0_DOMAIN = os.environ.get("AUTH0_DOMAIN")
AUTH0_CLIENT_ID = os.environ.get("AUTH0_CLIENT_ID")
AUTH0_CLIENT_SECRET = os.environ.get("AUTH0_CLIENT_SECRET")
AUTH0_REDIRECT_URI = os.environ.get("AUTH0_REDIRECT_URI")
AUTH0_AUDIENCE = os.environ.get("AUTH0_AUDIENCE")
AUTH0_SCOPE = os.environ.get("AUTH0_SCOPE", "openid profile email")
AUTH0_RESPONSE_TYPE = "code"


class Auth0OAuthError(RuntimeError):
    pass


def build_authorization_url(state: Optional[str] = None, nonce: Optional[str] = None) -> Dict[str, str]:
    if not AUTH0_DOMAIN:
        raise Auth0OAuthError("Missing AUTH0_DOMAIN")
    if not AUTH0_CLIENT_ID:
        raise Auth0OAuthError("Missing AUTH0_CLIENT_ID")
    if not AUTH0_REDIRECT_URI:
        raise Auth0OAuthError("Missing AUTH0_REDIRECT_URI")

    state = state or secrets.token_urlsafe(32)
    nonce = nonce or secrets.token_urlsafe(32)

    params = {
        "response_type": AUTH0_RESPONSE_TYPE,
        "client_id": AUTH0_CLIENT_ID,
        "redirect_uri": AUTH0_REDIRECT_URI,
        "scope": AUTH0_SCOPE,
        "state": state,
        "nonce": nonce,
    }
    if AUTH0_AUDIENCE:
        params["audience"] = AUTH0_AUDIENCE

    authorize_url = f"https://{AUTH0_DOMAIN}/authorize?{urllib.parse.urlencode(params)}"
    return {"url": authorize_url, "state": state, "nonce": nonce}


def exchange_code_for_tokens(code: str, redirect_uri: Optional[str] = None) -> Dict[str, object]:
    if not AUTH0_DOMAIN:
        raise Auth0OAuthError("Missing AUTH0_DOMAIN")
    if not AUTH0_CLIENT_ID:
        raise Auth0OAuthError("Missing AUTH0_CLIENT_ID")
    if not AUTH0_CLIENT_SECRET:
        raise Auth0OAuthError("Missing AUTH0_CLIENT_SECRET")

    redirect_uri = redirect_uri or AUTH0_REDIRECT_URI
    if not redirect_uri:
        raise Auth0OAuthError("Missing AUTH0_REDIRECT_URI")

    token_url = f"https://{AUTH0_DOMAIN}/oauth/token"
    payload = {
        "grant_type": "authorization_code",
        "client_id": AUTH0_CLIENT_ID,
        "client_secret": AUTH0_CLIENT_SECRET,
        "code": code,
        "redirect_uri": redirect_uri,
    }

    resp = requests.post(token_url, json=payload, timeout=30)
    if resp.status_code >= 400:
        raise Auth0OAuthError(f"Token exchange failed: {resp.status_code} {resp.text}")

    return resp.json()


def fetch_userinfo(access_token: str) -> Dict[str, object]:
    if not AUTH0_DOMAIN:
        raise Auth0OAuthError("Missing AUTH0_DOMAIN")

    userinfo_url = f"https://{AUTH0_DOMAIN}/userinfo"
    headers = {"Authorization": f"Bearer {access_token}"}
    resp = requests.get(userinfo_url, headers=headers, timeout=30)
    if resp.status_code >= 400:
        raise Auth0OAuthError(f"Userinfo request failed: {resp.status_code} {resp.text}")

    return resp.json()


def start_federated_login() -> Dict[str, str]:
    return build_authorization_url()


def complete_federated_login(code: str, redirect_uri: Optional[str] = None) -> Dict[str, object]:
    token_data = exchange_code_for_tokens(code, redirect_uri=redirect_uri)
    result = {"tokens": token_data}
    access_token = token_data.get("access_token")
    if access_token:
        result["userinfo"] = fetch_userinfo(access_token)
    return result
